# The R port must reproduce the Python package's values. The fixture in
# inst/parity/parity.json is generated by the Python package; if these fail,
# the two implementations have diverged and one of them is wrong.
fixture <- function() {
  skip_if_not_installed("jsonlite")
  p <- system.file("parity", "parity.json", package = "tracegamma")
  skip_if(p == "", "parity fixture not installed")
  jsonlite::fromJSON(p, simplifyVector = FALSE)
}

test_that("fitted parameters match the Python reference", {
  fx <- fixture()
  for (nm in names(fx$cases)) {
    cs <- fx$cases[[nm]]
    tg <- trace_gamma(lam = unlist(cs$lam))
    expect_equal(tg$a,  cs$params$a,  tolerance = 1e-12, info = nm)
    expect_equal(tg$nu, cs$params$nu, tolerance = 1e-12, info = nm)
    expect_equal(tg$b,  cs$params$b,  tolerance = 1e-12, info = nm)
    expect_identical(tg$branch, cs$branch, info = nm)
  }
})

test_that("ppf, cdf and pdf match the Python reference", {
  fx <- fixture(); qs <- unlist(fx$quantiles)
  for (nm in names(fx$cases)) {
    cs <- fx$cases[[nm]]; tg <- trace_gamma(lam = unlist(cs$lam))
    expect_equal(tg_ppf(tg, qs), unlist(cs$ppf), tolerance = 1e-10, info = nm)
    expect_equal(tg_cdf(tg, unlist(cs$ppf)), unlist(cs$cdf), tolerance = 1e-10, info = nm)
    expect_equal(tg_pdf(tg, unlist(cs$ppf)), unlist(cs$pdf), tolerance = 1e-10, info = nm)
    expect_equal(tg_cutoff(tg, 0.05), cs$cutoff05, tolerance = 1e-10, info = nm)
  }
})

test_that("defects and standardized cumulants match the Python reference", {
  fx <- fixture()
  for (nm in names(fx$cases)) {
    cs <- fx$cases[[nm]]; lam <- unlist(cs$lam)
    expect_equal(kurtosis_defect(lam),  cs$kurtosis_defect,  tolerance = 1e-12, info = nm)
    expect_equal(tail_rate_defect(lam), cs$tail_rate_defect, tolerance = 1e-12, info = nm)
    expect_equal(rho_ratio(lam),        cs$rho_ratio,        tolerance = 1e-12, info = nm)
    expect_equal(standardized_cumulant(lam, 3), cs$std_cumulant_3, tolerance = 1e-12, info = nm)
    expect_equal(standardized_cumulant(lam, 4), cs$std_cumulant_4, tolerance = 1e-12, info = nm)
  }
})

test_that("the exact Imhof survival matches the Python reference at the 5% cutoff", {
  fx <- fixture()
  for (nm in names(fx$cases)) {
    cs <- fx$cases[[nm]]
    expect_equal(imhof_sf(cs$cutoff05, unlist(cs$lam)),
                 cs$imhof_sf_at_cutoff05, tolerance = 1e-7, info = nm)
  }
})

test_that("the Welch branch, marginal cumulants and BB dilation match", {
  fx <- fixture()
  w <- trace_gamma(10, 20, 0)
  expect_identical(w$branch, fx$welch_branch$branch)
  expect_equal(w$a, fx$welch_branch$params$a, tolerance = 1e-12)
  expect_equal(w$nu, fx$welch_branch$params$nu, tolerance = 1e-12)
  for (m in names(fx$marginal_cumulants))
    expect_equal(unname(marginal_cumulants(as.numeric(m))),
                 unlist(fx$marginal_cumulants[[m]]), tolerance = 1e-12, info = m)
  for (e in fx$bb_scale_mixture) {
    a <- unlist(e$args)
    expect_equal(bb_scale_mixture(a[1], a[2], a[3], a[4]), e$value, tolerance = 1e-12)
  }
})
